pub(crate) fn columns(c: char) -> u16 {
    if c.is_ascii_graphic() || c == ' ' {
        return 1;
    }
    let code = u32::from(c);
    let index = RANGES.partition_point(|&(_, last, _)| last < code);
    match RANGES.get(index) {
        Some(&(first, _, width)) if first <= code => width,
        _ => 1,
    }
}
